mapper.select:
SELECT sm.id, sm.spot_id AS spotId, sm.media_type AS mediaType, sm.title, sm.file_name AS fileName, sm.file_url AS fileUrl, sm.file_size AS fileSize, sm.sort_no AS sortNo, sm.status, sm.created_at AS createdAt, sm.updated_at AS updatedAt FROM scenic_media sm WHERE 1 = 1
AND sm.spot_id = #{scenicMedia.spotId}
AND sm.media_type = #{scenicMedia.mediaType}
AND sm.title LIKE CONCAT('%',#{scenicMedia.title},'%')
AND sm.status = #{scenicMedia.status}
ORDER BY sm.sort_no ASC
